using System;using System.Globalization;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
sealed class IntegerSliderScale:FrameworkElement {
 readonly Slider slider;public IntegerSliderScale(Slider value){slider=value;Height=22;IsHitTestVisible=false;slider.AutoToolTipPlacement=System.Windows.Controls.Primitives.AutoToolTipPlacement.TopLeft;slider.AutoToolTipPrecision=0;slider.ValueChanged+=(s,e)=>InvalidateVisual();SetResourceReference(ForegroundProperty,"DeskMuted");}
 public static readonly DependencyProperty ForegroundProperty=DependencyProperty.Register("Foreground",typeof(Brush),typeof(IntegerSliderScale),new FrameworkPropertyMetadata(Brushes.Gray,FrameworkPropertyMetadataOptions.AffectsRender));
 protected override void OnRender(DrawingContext dc){double width=Math.Max(1,ActualWidth-16),range=slider.Maximum-slider.Minimum;if(range<=0)return;var brush=(Brush)GetValue(ForegroundProperty);double rough=range/Math.Max(1,width/45),power=Math.Pow(10,Math.Floor(Math.Log10(Math.Max(1,rough)))),step=new[]{1d,2,5,10}.SelectStep(rough/power)*power;for(double n=Math.Ceiling(slider.Minimum/step)*step;n<=slider.Maximum;n+=step){double x=8+width*(n-slider.Minimum)/range;dc.DrawLine(new Pen(brush,1),new Point(x,0),new Point(x,4));var text=new FormattedText(n.ToString("0",CultureInfo.InvariantCulture),CultureInfo.CurrentUICulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),9,brush,VisualTreeHelper.GetDpi(this).PixelsPerDip);dc.DrawText(text,new Point(Math.Max(0,Math.Min(ActualWidth-text.Width,x-text.Width/2)),5));}}
}
static class SliderScaleSteps {public static double SelectStep(this double[] values,double target){foreach(double value in values)if(value>=target)return value;return 10;}}
